-- Generated by npm run db:build. Initialize homepage capabilities once, preserving existing settings.
SET NAMES utf8mb4;
START TRANSACTION;
INSERT INTO site_settings (id, configuration)
SELECT 'capabilities', JSON_SET(capability_seed.configuration,
  '$.kicker."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".ourCapabilities')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.kicker."en"'))),
  '$.kicker."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".ourCapabilities')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.kicker."zh"'))),
  '$.titleLine1."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".fromConcept')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.titleLine1."en"'))),
  '$.titleLine1."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".fromConcept')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.titleLine1."zh"'))),
  '$.titleLine2."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".toReality')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.titleLine2."en"'))),
  '$.titleLine2."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".toReality')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.titleLine2."zh"'))),
  '$.description."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".fromInitialConceptToFinalCommissioningOurEngineeringAndManufacturingCapabilitiesAre')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.description."en"'))),
  '$.description."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".fromInitialConceptToFinalCommissioningOurEngineeringAndManufacturingCapabilitiesAre')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.description."zh"'))),
  '$.steps[0].label."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".concept')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[0].label."en"'))),
  '$.steps[0].label."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".concept')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[0].label."zh"'))),
  '$.steps[1].label."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".engineering')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[1].label."en"'))),
  '$.steps[1].label."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".engineering')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[1].label."zh"'))),
  '$.steps[2].label."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".design')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[2].label."en"'))),
  '$.steps[2].label."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".design')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[2].label."zh"'))),
  '$.steps[3].label."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".fabrication')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[3].label."en"'))),
  '$.steps[3].label."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".fabrication')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[3].label."zh"'))),
  '$.steps[4].label."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".assembly')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[4].label."en"'))),
  '$.steps[4].label."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".assembly')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[4].label."zh"'))),
  '$.steps[5].label."en"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."en".delivery')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[5].label."en"'))),
  '$.steps[5].label."zh"', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.translations."zh".delivery')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.steps[5].label."zh"'))),
  '$.image', COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(website.configuration, '$.assets."/assets/hero-03.jpg"')), 'null'), JSON_UNQUOTE(JSON_EXTRACT(capability_seed.configuration, '$.image'))))
FROM (SELECT CAST(CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci AS JSON) AS configuration) AS capability_seed
LEFT JOIN site_settings AS website ON website.id='website'
WHERE NOT EXISTS (SELECT 1 FROM site_settings WHERE id='capabilities');
INSERT INTO app_migrations (id) SELECT '2026-10-home-capabilities-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-home-capabilities-v1');
COMMIT;
